const r = await tools.exec_command({cmd:"python - <<'PY'
import csv,re
from pathlib import Path
p=Path('artifacts/sprint1/test-design/test-cases.v1.csv')
with p.open(newline='',encoding='utf-8') as f:
 rows=list(csv.DictReader(f))
print('rows',len(rows),'fields',len(rows[0]) if rows else 0)
print('headers',list(rows[0]) if rows else [])
ids=[r['用例编号'] for r in rows]
expected=[f'TC{i:03d}' for i in range(1,len(rows)+1)]
print('ids-contiguous',ids==expected,'unique',len(ids)==len(set(ids)))
prd=Path('artifacts/sprint1/prd/prd.md').read_text()
acs=set(re.findall(r'AC-\d{2}-\d+',prd))
covered=set()
for r in rows: covered.update(re.findall(r'AC-\d{2}-\d+',r['覆盖']))
print('prd-acs',len(acs),'covered-valid',len(acs&covered),'missing',sorted(acs-covered),'unknown',sorted(covered-acs))
req_pri={m.group(1):m.group(2) for m in re.finditer(r'^### (R\d{2}) · .*?\n(?:.*\n)*?- 优先级：(P[012])$',prd,re.M)}
# fallback block parser
req_pri={}
for block in re.split(r'(?=^### R\d{2} · )',prd,flags=re.M):
 m=re.match(r'### (R\d{2}) · ',block); q=re.search(r'- 优先级：(P[012])',block)
 if m and q:req_pri[m.group(1)]=q.group(1)
rank={'P0':0,'P1':1,'P2':2}
bad=[]
for r in rows:
 req=re.match(r'(R\d{2})',r['二级模块']).group(1)
 if rank[r['优先级']]<rank[req_pri[req]]:bad.append((r['用例编号'],req,r['优先级'],req_pri[req]))
print('priority-violations',bad)
print('blank-cells',[(r['用例编号'],k) for r in rows for k,v in r.items() if not v][:10])
mods=sorted(set((r['一级模块'],r['二级模块']) for r in rows))
print('requirements',len(mods))
for m,q in mods: print(m,'|',q)
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":10000}); text(r.output);

