import csv,re
p='artifacts/sprint1/test-design/test-cases.v1.csv'
with open(p,newline='',encoding='utf-8') as f: rows=list(csv.DictReader(f))
bad=[]
for r in rows:
 s=re.findall(r'(?m)^(\d+)\. ',r['操作步骤']); e=re.findall(r'(?m)^(\d+)\. ',r['预期结果'])
 if s!=[str(i) for i in range(1,len(s)+1)] or e!=[str(i) for i in range(1,len(e)+1)] or len(s)!=len(e):
  bad.append((r['用例编号'],s,e))
print('numbered-step-result-pairs',len(rows)-len(bad),'/',len(rows),'bad',bad)
refs={'FD':set(f'FD{i:02d}' for i in range(1,11)),'BD':set(f'BD{i:02d}' for i in range(1,18)),'I':set(f'I{i:02d}' for i in range(1,12))}
unknown=[]
for r in rows:
 for prefix,valid in refs.items():
  for x in re.findall(prefix+r'\d{2}',r['覆盖']):
   if x not in valid: unknown.append((r['用例编号'],x))
print('unknown-design-refs',unknown)
for req in range(1,21):
 key=f'R{req:02d} ·'
 rs=[r for r in rows if r['二级模块'].startswith(key)]
 print(f'R{req:02d}',len(rs),','.join(r['用例编号'] for r in rs))
